t.add("docimology_discrimination_coefficient_help_part_2", "Une valeur positive souligne une question qui conforte les meilleurs tandis qu'une valeur n\u00e9gative signifie que ce sont les apprenants ayant les moins bonnes notes qui ont le mieux r\u00e9pondu.", "quiz", "fr");
t.add("docimology_discrimination_coefficient_help_part_3", "Quand une question a un co\u00e9fficient de discrimination n\u00e9gatif, cela signifie qu'elle p\u00e9nalise les meilleurs. Il vaut donc mieux \u00e9viter de telles questions.", "quiz", "fr");
t.add("docimology_discrimination_coefficient_help_part_4", "Il est \u00e0 remarquer que, si tous les \u00e9tudiants obtiennent le m\u00eame score \u00e0 une question, le co\u00e9fficient ne sera pas d\u00e9fini.", "quiz", "fr");
